#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

DOMAIN="elizarowa.com"
STACK="elizarowa-com"
REGION="us-east-1"
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"

# stack_output KEY: значение output'а CloudFormation-стека (пусто, если нет).
stack_output() {
  aws cloudformation describe-stacks --region "$REGION" --stack-name "$STACK" \
    --query "Stacks[0].Outputs[?OutputKey=='$1'].OutputValue" --output text 2>/dev/null | sed 's/^None$//'
}

# public_ns: NS-записи домена глазами публичного резолвера Google.
public_ns() {
  if command -v dig >/dev/null 2>&1; then
    dig +short NS "$DOMAIN" @8.8.8.8 2>/dev/null
  else
    curl -fsS "https://dns.google/resolve?name=$DOMAIN&type=NS" 2>/dev/null | grep -o '"data":"[^"]*"' | cut -d'"' -f4
  fi
}

run_wizard() {

TOTAL_STAGES=9

banner "elizarowa.com → AWS (S3 + CloudFront + Route 53)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Проверка инструментов и аккаунта AWS"
say "Нужны: aws CLI v2 (с правами администратора в нужном аккаунте), gh CLI, git."
for tool in aws gh git curl; do
  if command -v "$tool" >/dev/null 2>&1; then step "$tool ✓"; else warn "$tool не найден — установите и перезапустите мастер"; exit 1; fi
done
if ! gh auth status >/dev/null 2>&1; then
  warn "gh не авторизован. Выполните: gh auth login — и перезапустите мастер."
  exit 1
fi
if ! ACCOUNT_ID=$(aws sts get-caller-identity --query Account --output text 2>/dev/null); then
  warn "aws CLI не авторизован. Выполните: aws configure (или aws sso login) — и перезапустите мастер."
  exit 1
fi
say ""
say "AWS-аккаунт: ${BOLD}$ACCOUNT_ID${RESET}  ($(aws sts get-caller-identity --query Arn --output text))"
confirm "Это тот аккаунт, где будет жить сайт?" || { warn "Переключите профиль (AWS_PROFILE=...) и перезапустите."; exit 1; }

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "IAM-роль для GitHub Actions (OIDC)"
say "OIDC между GitHub и AWS уже настроен. Нужен ARN роли, которую будет брать деплой."
open_url "https://console.aws.amazon.com/iam/home#/roles"
step "IAM → Roles → роль для GitHub Actions → скопируйте ARN (arn:aws:iam::...:role/...)."
ask AWS_ROLE_ARN "ARN роли:"
DEPLOY_ROLE_NAME="${AWS_ROLE_ARN##*/}"
if ! TRUST=$(aws iam get-role --role-name "$DEPLOY_ROLE_NAME" --query 'Role.AssumeRolePolicyDocument' --output json 2>/dev/null); then
  warn "Роль $DEPLOY_ROLE_NAME не найдена в аккаунте $ACCOUNT_ID."; exit 1
fi
say ""
say "Проверяю, кому роль доверяет (trust policy):"
if grep -q 'repo:bleschunov/elizarowa_com:ref:refs/heads/main' <<<"$TRUST"; then
  step "${GREEN}✓${RESET} только ветка main репозитория bleschunov/elizarowa_com — отлично."
elif grep -q 'repo:bleschunov/elizarowa_com' <<<"$TRUST"; then
  warn "Роль доверяет репозиторию, но не только ветке main (любая ветка/PR сможет деплоить)."
  note "Рекомендуется условие: token.actions.githubusercontent.com:sub = repo:bleschunov/elizarowa_com:ref:refs/heads/main"
else
  warn "В trust policy нет ограничения на репозиторий bleschunov/elizarowa_com!"
  note "Это значит, что роль может взять ЛЮБОЙ репозиторий GitHub. Исправьте условие sub перед продолжением:"
  note "  token.actions.githubusercontent.com:sub = repo:bleschunov/elizarowa_com:ref:refs/heads/main"
  note "  token.actions.githubusercontent.com:aud = sts.amazonaws.com"
  confirm "Продолжить всё равно?" || exit 1
fi
set_secret AWS_ROLE_ARN "$AWS_ROLE_ARN"
note "Права на бакет и CloudFront стек выдаст этой роли сам (этап 7)."
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "DNS-зона в Route 53"
say "Создаю зону $DOMAIN в Route 53 с копией текущих записей:"
step "сайт ($DOMAIN, www) — пока на старый VPS, чтобы переключение NS прошло без простоя;"
step "почта Mailgun — MX, SPF, DKIM (mx._domainkey), DMARC."
note "Стоимость зоны: ~0.50 \$/мес. Повторный запуск безопасен."
confirm "Создать/обновить стек $STACK?" || exit 1
DEPLOY_ROLE_NAME="$DEPLOY_ROLE_NAME" "$REPO_ROOT/infra/deploy.sh" dns
NAME_SERVERS=$(stack_output NameServers)
HOSTED_ZONE_ID=$(stack_output HostedZoneId)
say ""
say "NS-серверы Route 53 (понадобятся на этапе 5):"
for ns in $NAME_SERVERS; do step "${BOLD}$ns${RESET}"; done
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Squarespace: сверить DNS-записи"
say "После смены NS записи из Squarespace перестанут действовать. Убедимся, что ничего не потеряли."
open_url "https://account.squarespace.com/domains"
step "Domains → $DOMAIN → DNS → DNS Settings."
step "Сравните ваши записи (Custom records) со списком ниже — это то, что уже есть в Route 53:"
say ""
aws route53 list-resource-record-sets --hosted-zone-id "$HOSTED_ZONE_ID" \
  --query "ResourceRecordSets[?Type!='NS' && Type!='SOA'].[Name,Type,join(' | ',ResourceRecords[].Value)]" \
  --output text | sed 's/^/    /'
say ""
note "Записи-пресеты самого Squarespace (например, _domainconnect) переносить не нужно."
note "Если в Squarespace есть ДРУГИЕ записи (другие поддомены, верификации Google/Yandex и т.п.),"
note "остановитесь (Ctrl-C), добавьте их в infra/site.yaml и запустите мастер заново."
confirm "Все нужные записи есть в списке выше?" || exit 1

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Squarespace: переключить NS на Route 53"
open_url "https://account.squarespace.com/domains"
step "Domains → $DOMAIN → DNS."
step "Если там есть DNSSEC и он включён — выключите его и сохраните (сейчас у домена DS-записи нет, скорее всего уже выключен)."
step "Domain Nameservers → Use Custom Nameservers."
step "Удалите старые значения и впишите четыре сервера:"
for ns in $NAME_SERVERS; do say "      ${BOLD}$ns${RESET}"; done
step "Сохраните. Регистрация домена остаётся в Squarespace — меняется только DNS."
note "Откат при проблемах: там же выбрать «Use Squarespace Nameservers»."
pause "Сохранили новые NS? Enter —"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Ждём, пока интернет увидит новые NS"
say "Обычно от 10 минут до нескольких часов (иногда до 48 ч). Проверяю каждые 30 секунд."
note "Можно прервать (Ctrl-C) и перезапустить мастер позже — этапы 1–5 безопасно пройти ещё раз."
while true; do
  current=$(public_ns | tr '\n' ' ' || true)
  if grep -q 'awsdns' <<<"$current"; then
    printf '\n'; step "${GREEN}✓${RESET} делегирование видно: $current"
    break
  fi
  printf '\r  %s… сейчас: %s%s   ' "$DIM" "${current:-нет ответа}" "$RESET"
  sleep 30
done
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Сертификат, S3 и CloudFront"
say "Создаю HTTPS-сертификат (проверяется через Route 53 автоматически), приватный бакет,"
say "CloudFront с заголовками безопасности и переключаю $DOMAIN и www на CloudFront."
note "Занимает 5–20 минут. Старый VPS после этого перестанет получать трафик (кроме закешированных DNS)."
confirm "Развернуть сайт в AWS?" || exit 1
DEPLOY_ROLE_NAME="$DEPLOY_ROLE_NAME" "$REPO_ROOT/infra/deploy.sh" site
S3_BUCKET=$(stack_output BucketName)
CLOUDFRONT_DISTRIBUTION_ID=$(stack_output DistributionId)
set_secret S3_BUCKET "$S3_BUCKET"
set_secret CLOUDFRONT_DISTRIBUTION_ID "$CLOUDFRONT_DISTRIBUTION_ID"
# Если раньше эти значения были переменными репозитория — убираем, чтобы не дублировались.
for v in AWS_ROLE_ARN S3_BUCKET CLOUDFRONT_DISTRIBUTION_ID; do gh variable delete "$v" >/dev/null 2>&1 || true; done
note "Бакет пока пустой — до первого деплоя сайт будет отвечать 404."
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Первый деплой"
say "Деплой — GitHub Actions (.github/workflows/deploy.yml): заливает site/ в S3 и сбрасывает кеш CloudFront."
if confirm "Изменения (папка site/ и новый workflow) уже в ветке main на GitHub?"; then
  gh workflow run deploy.yml --ref main
  note "Запустил workflow вручную."
else
  step "Закоммитьте и запушьте изменения в main — деплой запустится сам."
  pause "Запушили? Enter —"
fi
sleep 5
RUN_ID=$(gh run list --workflow deploy.yml --limit 1 --json databaseId --jq '.[0].databaseId' 2>/dev/null || true)
if [[ -n "$RUN_ID" ]]; then
  gh run watch "$RUN_ID" --exit-status || warn "Деплой упал — смотрите: gh run view $RUN_ID --log-failed"
fi
say ""
for url in "https://$DOMAIN/" "https://www.$DOMAIN/" "https://$DOMAIN/about" "https://$DOMAIN/blog"; do
  code=$(curl -s -o /dev/null -w '%{http_code}' "$url" || echo "---")
  step "$url → $code"
done
note "Ожидается 200 для $DOMAIN и 301 для www. Если старый IP ещё в кеше вашего DNS — подождите."
open_url "https://$DOMAIN/"
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Уборка старой инфраструктуры"
say "Сайт больше не отправляет заявки в Telegram и не использует VPS, Keystatic и SSH-деплой."
say ""
step "Telegram-бот заявок: @BotFather → /mybots → бот → API Token → Revoke current token"
note "(если этот бот больше нигде не нужен — иначе токен всё равно стоит перевыпустить)."
open_url "https://t.me/BotFather"
pause "Готово? Enter —"
if confirm "Удалить старые GitHub-секреты SSH_HOST, SSH_USER, SSH_PRIVATE_KEY, DEPLOY_PATH?"; then
  for s in SSH_HOST SSH_USER SSH_PRIVATE_KEY DEPLOY_PATH; do
    gh secret delete "$s" >/dev/null 2>&1 && step "удалён $s" || note "$s — не найден"
  done
fi
step "Keystatic: удалите его GitHub App / OAuth App и отзовите установку."
open_url "https://github.com/settings/apps"
note "Также проверьте https://github.com/settings/developers (OAuth Apps) и https://github.com/settings/installations"
pause "Готово? Enter —"
step "VPS: через несколько дней (когда старые DNS-кеши истекут) — pm2 delete elizarowa-com,"
step "удалите публичный ключ деплоя из ~deploy/.ssh/authorized_keys и отключите/удалите сервер."
pause

finish
}

run_wizard "$@"; exit
